    h, w = len(grid), len(grid[0])
    marker = next(v for row in grid for v in row if v not in (grid[0][0],))
    # Draw between pairs of markers that share a row or column, without
    # crossing another marker.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(cols, cols[1:]):
